css:
.resilience-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1100px;
    margin: 0 auto;
    padding: 24px;
    color: #e6edf6;
    background: radial-gradient(120% 120% at 12% 0%, #16233b 0%, #0e1626 55%, #0a101c 100%);
    border-radius: 18px;
}

.resilience-container * {
    box-sizing: border-box;
}

.resilience-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #102a4a 0%, #15487a 52%, #1f8f8a 100%);
    color: #f2f8ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 16px 38px rgba(4, 12, 26, 0.55);
    border: 1px solid rgba(86, 196, 211, 0.22);
}

.resilience-header h1 {
    margin: 12px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.resilience-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #ffd27a;
    background: rgba(255, 210, 122, 0.10);
    border: 1px solid rgba(255, 210, 122, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.resilience-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.56;
    color: #cfe6ee;
}

.resilience-firmbar {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
}

.resilience-firm-fact {
    flex: 1;
    background: #131f33;
    border-radius: 13px;
    padding: 13px 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    border: 1px solid rgba(120, 150, 190, 0.16);
    box-shadow: 0 6px 16px rgba(4, 12, 26, 0.35);
}

.resilience-fact-flagship { border-left: 5px solid #e06c4f; }
.resilience-fact-moat { border-left: 5px solid #36c0a8; }
.resilience-fact-rival { border-left: 5px solid #c9528f; }

.resilience-fact-label {
    font-size: 0.70rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #8aa0bf;
}

.resilience-fact-value {
    font-size: 0.92rem;
    font-weight: 700;
    color: #e6edf6;
    line-height: 1.35;
}

.resilience-fact-flagship .resilience-fact-value { color: #f0a08b; }
.resilience-fact-moat .resilience-fact-value { color: #6fd9c6; }
.resilience-fact-rival .resilience-fact-value { color: #e58cbb; }

.resilience-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb4d2;
    margin-bottom: 16px;
    padding: 2px 4px;
}

.resilience-period-counter #currentDay,
.resilience-period-counter #maxPeriods {
    font-weight: 800;
    color: #56c4d3;
}

.resilience-round-name {
    background: rgba(86, 196, 211, 0.16);
    color: #7fdce8;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.resilience-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffce82;
    background: rgba(255, 206, 130, 0.12);
    border: 1px solid rgba(255, 206, 130, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.resilience-status-cards {
    display: grid;
    grid-template-columns: 1.35fr 1fr 1fr 1fr 1fr;
    gap: 13px;
    margin-bottom: 16px;
}

.resilience-status-card {
    background: #131f33;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 8px 20px rgba(4, 12, 26, 0.40);
    border: 1px solid rgba(120, 150, 190, 0.14);
    border-top: 4px solid #56c4d3;
}

.resilience-card-score {
    border-top-color: #56c4d3;
    background: linear-gradient(160deg, #15263f 0%, #112038 100%);
}
.resilience-card-dependence { border-top-color: #e06c4f; }
.resilience-card-newrev { border-top-color: #36c0a8; }
.resilience-card-exposure { border-top-color: #c9528f; }
.resilience-card-budget { border-top-color: #ffce82; }

.resilience-label {
    font-size: 0.70rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa0bf;
}

.resilience-value {
    font-size: 1.95rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 5px 0 3px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.resilience-value-hero {
    font-size: 3rem;
    color: #56c4d3;
    text-shadow: 0 0 22px rgba(86, 196, 211, 0.35);
}

.resilience-card-dependence .resilience-value { color: #f0a08b; }
.resilience-card-newrev .resilience-value { color: #6fd9c6; }
.resilience-card-exposure .resilience-value { color: #e58cbb; }
.resilience-card-budget .resilience-value { color: #ffd79a; }

.resilience-sublabel {
    font-size: 0.74rem;
    color: #7e93b2;
    line-height: 1.38;
}

/* state-driven accents on the hero score */
.resilience-card-score.resilience-score-good { border-top-color: #36c0a8; }
.resilience-card-score.resilience-score-good .resilience-value-hero { color: #5fe0c7; text-shadow: 0 0 22px rgba(95, 224, 199, 0.40); }
.resilience-card-score.resilience-score-bad { border-top-color: #e0594f; }
.resilience-card-score.resilience-score-bad .resilience-value-hero { color: #ef7d72; text-shadow: 0 0 22px rgba(224, 89, 79, 0.35); }

.resilience-card-dependence.resilience-dep-good .resilience-value { color: #6fd9c6; }
.resilience-card-dependence.resilience-dep-good { border-top-color: #36c0a8; }

.resilience-roi-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #131f33;
    border: 1px solid rgba(120, 150, 190, 0.18);
    color: #9fb4d2;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.resilience-roi-bar #roiDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #ffd79a;
    font-weight: 800;
}

.resilience-roi-bar.resilience-roi-good #roiDisplay { color: #5fe0c7; }
.resilience-roi-bar.resilience-roi-bad #roiDisplay { color: #ef7d72; }

.resilience-briefing {
    display: flex;
    gap: 14px;
    background: #131f33;
    border-left: 5px solid #56c4d3;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(4, 12, 26, 0.35);
}

.resilience-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.resilience-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #aee7ef;
    margin-bottom: 6px;
}

.resilience-briefing-text {
    font-size: 0.95rem;
    line-height: 1.56;
    color: #c4d4e8;
}

.resilience-briefing-text strong { color: #7fdce8; }
.resilience-briefing-text em { color: #ffce82; font-style: italic; }

.resilience-controls {
    background: #101a2c;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(4, 12, 26, 0.35);
    border: 1px solid rgba(120, 150, 190, 0.14);
}

.resilience-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #e6edf6;
    border-bottom: 2px solid rgba(120, 150, 190, 0.20);
    padding-bottom: 8px;
}

.resilience-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #bcd0ea;
    margin: 14px 0 6px;
}

.resilience-container select,
.resilience-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid rgba(120, 150, 190, 0.34);
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #182640;
    color: #e6edf6;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.resilience-container select option {
    background-color: #182640;
    color: #e6edf6;
}

.resilience-container select:focus,
.resilience-container input[type="number"]:focus {
    outline: none;
    border-color: #56c4d3;
    box-shadow: 0 0 0 3px rgba(86, 196, 211, 0.22);
}

.resilience-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #56c4d3;
}

.resilience-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb4d2;
    margin-top: 4px;
}

.resilience-range-readout span:nth-child(2) {
    color: #56c4d3;
    font-weight: 800;
}

.resilience-hint {
    font-size: 0.8rem;
    color: #8297b6;
    margin-top: 8px;
    line-height: 1.45;
    font-style: italic;
    border-left: 3px solid rgba(255, 206, 130, 0.45);
    padding-left: 10px;
}

.resilience-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.resilience-container .btn-primary {
    background: linear-gradient(135deg, #15487a 0%, #1f9f97 100%);
    border: none;
    color: #ffffff;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 10px 22px rgba(20, 120, 130, 0.40);
}

.resilience-container .btn-primary:hover {
    filter: brightness(1.10);
}

.resilience-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid rgba(120, 150, 190, 0.40);
    color: #9fb4d2;
    background: transparent;
}

.resilience-coach {
    background: linear-gradient(160deg, #0c1830 0%, #11243f 100%);
    color: #d4e6f2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 10px 24px rgba(4, 12, 26, 0.45);
    border: 1px solid rgba(86, 196, 211, 0.20);
}

.resilience-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd27a;
    margin-bottom: 8px;
}

.resilience-coach-body {
    font-size: 0.95rem;
    line-height: 1.56;
}

.resilience-coach-body strong { color: #7fdce8; }
.resilience-coach-body em { color: #ffce82; font-style: italic; }

.resilience-history,
.resilience-chart {
    background: #101a2c;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(4, 12, 26, 0.35);
    border: 1px solid rgba(120, 150, 190, 0.14);
}

.resilience-history h3,
.resilience-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #e6edf6;
}

.resilience-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c4d4e8;
}

.resilience-container table#usfHistoryTable th {
    background: #16243d;
    color: #7fdce8;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.70rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(86, 196, 211, 0.30);
}

.resilience-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(120, 150, 190, 0.14);
    color: #c4d4e8;
}

.resilience-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(22, 36, 61, 0.55);
}

.resilience-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .resilience-container {
        padding: 14px;
    }
    .resilience-header h1 {
        font-size: 1.7rem;
    }
    .resilience-firmbar {
        flex-direction: column;
    }
    .resilience-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .resilience-value {
        font-size: 1.7rem;
    }
    .resilience-value-hero {
        font-size: 2.4rem;
    }
    .resilience-clock {
        margin-left: 0;
    }
    .resilience-period-counter {
        font-size: 0.88rem;
    }
    .resilience-roi-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .resilience-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ===== Completion debrief (v1.1.0) — namespaced .rr-cm-*, append-only. Dark slate/teal palette. ===== */
.rr-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #e6edf6;
    background: radial-gradient(120% 120% at 12% 0%, #16233b 0%, #0e1626 55%, #0a101c 100%);
    border: 1px solid rgba(86, 196, 211, 0.20); border-radius: 16px; padding: 22px 24px 24px; max-width: 720px; margin: 8px auto;
    box-shadow: 0 14px 36px rgba(4, 8, 16, 0.55); }
.rr-cm-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
    border-bottom: 1px solid rgba(86, 196, 211, 0.18); padding-bottom: 14px; margin-bottom: 16px; }
.rr-cm-verdict { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.3px; line-height: 1.15; }
.rr-cm-good .rr-cm-verdict { color: #36c0a8; }
.rr-cm-mid  .rr-cm-verdict { color: #ffce82; }
.rr-cm-bad  .rr-cm-verdict { color: #ff8a9b; }
.rr-cm-score { display: flex; align-items: baseline; gap: 6px; white-space: nowrap; }
.rr-cm-score-num { font-size: 2.1rem; font-weight: 800; color: #ffffff; }
.rr-cm-score-max { font-size: 1rem; color: #9fb4d2; }
.rr-cm-grade { margin-left: 10px; font-size: 0.82rem; font-weight: 700; color: #bff0f6;
    background: rgba(86, 196, 211, 0.14); border: 1px solid rgba(86, 196, 211, 0.30); padding: 3px 10px; border-radius: 999px; }
.rr-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 16px; }
.rr-cm-kpi { background: rgba(22, 35, 59, 0.6); border: 1px solid rgba(86, 196, 211, 0.16); border-radius: 12px; padding: 12px 10px; text-align: center; }
.rr-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #ffffff; }
.rr-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.6px; color: #9fb4d2; margin-top: 4px; }
.rr-cm-kpi.rr-cm-ok { border-color: rgba(54, 192, 168, 0.5); box-shadow: inset 0 0 0 1px rgba(54, 192, 168, 0.14); }
.rr-cm-kpi.rr-cm-no { border-color: rgba(255, 138, 155, 0.42); }
.rr-cm-gates-h, .rr-cm-insights-h { font-size: 0.74rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #ffce82; margin: 6px 0 8px; }
.rr-cm-gates { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.rr-cm-chip { font-size: 0.8rem; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.rr-cm-chip-ok { color: #052620; background: #36c0a8; }
.rr-cm-chip-no { color: #ffd9df; background: rgba(255, 138, 155, 0.16); border-color: rgba(255, 138, 155, 0.42); }
.rr-cm-insights { margin: 0; padding-left: 18px; }
.rr-cm-insights li { font-size: 0.92rem; line-height: 1.5; color: #c9d6e8; margin-bottom: 8px; }
@media (max-width: 560px) { .rr-cm-kpis { grid-template-columns: repeat(2, 1fr); } .rr-cm-head { flex-direction: column; align-items: flex-start; } }

