(function() {
    'use strict';

    class RevenueResilienceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Revenue Resilience`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Meridian Insights Group) ----
            this.REVENUE = 96;            // A$96M annual revenue
            this.BUDGET = 12;             // A$12M ring-fenced innovation budget
            this.START_SCORE = 38;        // baseline resilience score (0–100)
            this.START_DEP = 74;          // % revenue in the flagship Sector Reports line
            this.START_EXPOSURE = 68;     // % of revenue in the path of AI/API disruption
            this.DEP_TARGET = 60;         // board mandate: dependence < 60% in 24 months
            this.SCORE_TARGET = 70;       // resilience score the board wants

            // Concept "true" answers (the modelled path).
            this.TRUE_BRITTLE = `stream`;
            this.TRUE_ASSET = `data`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    score: this.START_SCORE,         // resilience score 0–100
                    dependence: this.START_DEP,      // single-stream dependence %
                    newRev: 0,                        // projected 24-month new-stream revenue (A$M)
                    exposure: this.START_EXPOSURE,    // disruption exposure %
                    budgetLeft: this.BUDGET,          // A$M remaining
                    committed: 0,                     // A$M committed so far
                    roi: 0,                           // innovation ROI multiple on committed spend

                    // ---- Sticky run-defining penalty flags (gate the top verdict + cap KPIs) ----
                    polishedCashCow: false,           // headline anti-pattern: defended the flagship instead of diversifying
                    singleBet: false,                 // recreated concentration with one new product
                    cannibalParalysis: false,         // refused to cannibalise; ceded the AI revenue to rivals
                    noProcess: false,                 // funded products but no explorative pattern
                    oneSizeGov: false,                // judged ventures by the core's margin/quarterly targets
                    noHedge: false,                   // built no hedge against residual disruption
                    diagnosisRight: false,            // read the brittleness map correctly in R1

                    scoreHistory: [this.START_SCORE],
                    depHistory: [this.START_DEP],
                    exposureHistory: [this.START_EXPOSURE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    brittle: `renewal`,
                    asset: `brand`,
                    horizon: `h1`,
                    urgency: 35,
                    streams: `cashcow`,
                    cannibal: `refuse`,
                    invest: 2,
                    pattern: `none`,
                    governance: `core`,
                    cadence: `annual`,
                    exploreFund: 0.5,
                    hedge: `none`,
                    lockin: `milk`,
                    pitch: `decorate`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const ds = state.domainState;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const br = document.getElementById(`brittleInput`);
                const as = document.getElementById(`assetInput`);
                const ho = document.getElementById(`horizonInput`);
                const ur = document.getElementById(`urgencyInput`);
                if (br) decisions.brittle = br.value;
                if (as) decisions.asset = as.value;
                if (ho) decisions.horizon = ho.value;
                if (ur) decisions.urgency = parseInt(ur.value, 10);
                if (!Number.isFinite(decisions.urgency) || decisions.urgency < 0 || decisions.urgency > 100) {
                    warn(`warn_urgency_range`); return false;
                }
            } else if (round === 2) {
                const st = document.getElementById(`streamsInput`);
                const ca = document.getElementById(`cannibalInput`);
                const iv = document.getElementById(`investInput`);
                if (st) decisions.streams = st.value;
                if (ca) decisions.cannibal = ca.value;
                if (iv) decisions.invest = parseFloat(iv.value);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_value`); return false;
                }
                if (decisions.invest > ds.budgetLeft + 0.0001) {
                    warn(`warn_invest_budget`); return false;
                }
            } else if (round === 3) {
                const pa = document.getElementById(`patternInput`);
                const go = document.getElementById(`governanceInput`);
                const cd = document.getElementById(`cadenceInput`);
                const ef = document.getElementById(`exploreFundInput`);
                if (pa) decisions.pattern = pa.value;
                if (go) decisions.governance = go.value;
                if (cd) decisions.cadence = cd.value;
                if (ef) decisions.exploreFund = parseFloat(ef.value);
                if (!Number.isFinite(decisions.exploreFund) || decisions.exploreFund < 0) {
                    warn(`warn_explorefund_value`); return false;
                }
                if (decisions.exploreFund > ds.budgetLeft + 0.0001) {
                    warn(`warn_explorefund_budget`); return false;
                }
            } else if (round === 4) {
                const he = document.getElementById(`hedgeInput`);
                const lo = document.getElementById(`lockinInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (he) decisions.hedge = he.value;
                if (lo) decisions.lockin = lo.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let scoreDelta = 0, depDelta = 0, newRevDelta = 0, exposureDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Diagnose the resilience gap. No spend; sets up the cycle. ----
                switch (d.brittle) {
                    case `stream`:
                        ds.diagnosisRight = true;
                        scoreDelta += 5; coachKey = `coach_r1_stream`; break;
                    case `client`:
                        scoreDelta += 1; coachKey = `coach_r1_client`; break;
                    case `renewal`:
                        scoreDelta -= 1; coachKey = `coach_r1_renewal`; break;
                    case `none`:
                        scoreDelta -= 4; exposureDelta += 3; coachKey = `coach_r1_none`; break;
                }

                switch (d.asset) {
                    case `data`: scoreDelta += 4; if (d.brittle === `stream`) coachKey = `coach_r1_sharp`; break;
                    case `brand`: scoreDelta += 0; break;
                    case `repackage`: scoreDelta -= 3; exposureDelta += 2; coachKey = `coach_r1_repackage`; break;
                }

                switch (d.horizon) {
                    case `balanced`: scoreDelta += 4; break;
                    case `h1`: scoreDelta -= 2; coachKey = `coach_r1_h1`; break;
                    case `h3only`: scoreDelta -= 3; break;
                }

                // Ambition sets how seriously the cycle treats the disruption.
                if (d.urgency >= 60) { scoreDelta += 3; }
                else if (d.urgency <= 25) { scoreDelta -= 3; }

                summaryKey = (d.brittle === `stream` && d.asset === `data` && d.horizon === `balanced`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Fund the diversification portfolio. The headline anti-pattern lives here. ----
                spend = d.invest;

                switch (d.streams) {
                    case `cashcow`:
                        // HEADLINE ANTI-PATTERN: polishing the cash cow. STICKY.
                        ds.polishedCashCow = true;
                        scoreDelta -= 10; depDelta += 1; newRevDelta += 0; exposureDelta += 4;
                        coachKey = `coach_r2_cashcow`;
                        break;
                    case `single`:
                        // Single-bet diversification — recreates concentration. STICKY.
                        ds.singleBet = true;
                        scoreDelta += 4; depDelta -= 4; newRevDelta += 7 + spend * 0.8; exposureDelta -= 5;
                        coachKey = `coach_r2_single`;
                        break;
                    case `portfolio`:
                        // The modelled path — a real portfolio with staggered timing.
                        scoreDelta += 14; depDelta -= 9; newRevDelta += 9 + spend * 1.3; exposureDelta -= 12;
                        coachKey = `coach_r2_portfolio`;
                        break;
                    case `scatter`:
                        // All five thinly — no stream reaches escape velocity.
                        scoreDelta += 2; depDelta -= 3; newRevDelta += 4 + spend * 0.4; exposureDelta -= 4;
                        coachKey = `coach_r2_scatter`;
                        break;
                }

                switch (d.cannibal) {
                    case `onterms`:
                        scoreDelta += 6; depDelta -= 4; newRevDelta += 4; exposureDelta -= 6;
                        if (d.streams === `portfolio`) coachKey = `coach_r2_onterms`;
                        break;
                    case `refuse`:
                        // Cannibalisation paralysis — cede the AI revenue to rivals. STICKY.
                        ds.cannibalParalysis = true;
                        scoreDelta -= 5; exposureDelta += 6; coachKey = `coach_r2_refuse`;
                        break;
                    case `ignore`:
                        scoreDelta -= 3; exposureDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r2_ignore`;
                        break;
                }

                // Funding adequacy: a portfolio needs enough capital to reach first revenue,
                // but over-committing now starves Rounds 3 and 4.
                if (d.streams === `portfolio` || d.streams === `single`) {
                    if (spend < 3) { newRevDelta -= 6; scoreDelta -= 4; coachKey = `coach_r2_underfund`; }
                    else if (spend > 8) { scoreDelta -= 5; coachKey = `coach_r2_overcommit`; }
                }

                summaryKey = (d.streams === `portfolio` && d.cannibal === `onterms`) ? `sum_r2_good` :
                             (ds.polishedCashCow ? `sum_r2_cashcow` :
                             (ds.singleBet ? `sum_r2_single` :
                             (ds.cannibalParalysis ? `sum_r2_refuse` : `sum_r2_weak`)));
            } else if (round === 3) {
                // ---- Fund the explorative process pattern + ambidextrous governance. ----
                spend = d.exploreFund;

                switch (d.pattern) {
                    case `factory`:
                        scoreDelta += 13; newRevDelta += 5; exposureDelta -= 8; coachKey = `coach_r3_factory`; break;
                    case `pipeline`:
                        scoreDelta += 9; newRevDelta += 3; exposureDelta -= 5; break;
                    case `signals`:
                        scoreDelta += 6; exposureDelta -= 4; break;
                    case `none`:
                        // Products without a process. STICKY.
                        ds.noProcess = true;
                        scoreDelta -= 9; exposureDelta += 5; coachKey = `coach_r3_noprocess`; break;
                }

                switch (d.governance) {
                    case `ambidextrous`:
                        scoreDelta += 8; coachKey = (d.pattern === `factory` ? `coach_r3_ambidextrous` : coachKey); break;
                    case `core`:
                        // One-size governance — the core's logic strangles explore. STICKY.
                        ds.oneSizeGov = true;
                        scoreDelta -= 7; newRevDelta -= 4; coachKey = `coach_r3_coregov`; break;
                    case `nogov`:
                        scoreDelta -= 4; coachKey = (coachKey === `coach_default` ? `coach_r3_nogov` : coachKey); break;
                }

                switch (d.cadence) {
                    case `leading`: scoreDelta += 5; break;
                    case `annual`: scoreDelta -= 2; break;
                    case `revenue`:
                        // Watching revenue only kills ventures before they validate — explore strangled.
                        scoreDelta -= 4; newRevDelta -= 3;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_revenueonly`;
                        break;
                }

                // Under-funding the engine after the escalation undercuts everything.
                if (d.pattern !== `none` && spend < 1) {
                    scoreDelta -= 4; coachKey = `coach_r3_starve`;
                }

                summaryKey = (d.pattern === `factory` && d.governance === `ambidextrous` && d.cadence === `leading`) ? `sum_r3_good` :
                             (ds.noProcess ? `sum_r3_noprocess` :
                             (ds.oneSizeGov ? `sum_r3_coregov` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Hedge the residual disruption + pitch the board. ----
                switch (d.hedge) {
                    case `multi`:
                        scoreDelta += 11; exposureDelta -= 14; coachKey = `coach_r4_multi`; break;
                    case `partner`:
                        scoreDelta += 7; exposureDelta -= 9; break;
                    case `acquire`:
                        scoreDelta += 6; newRevDelta += 4; exposureDelta -= 7; break;
                    case `none`:
                        // No hedge — assumes you out-innovate AI on every front. STICKY.
                        ds.noHedge = true;
                        scoreDelta -= 8; exposureDelta += 7; coachKey = `coach_r4_nohedge`; break;
                }

                switch (d.lockin) {
                    case `lockin`:
                        scoreDelta += 5; depDelta -= 2; exposureDelta -= 4; break;
                    case `milk`:
                        scoreDelta -= 1; break;
                    case `dump`:
                        // Killing the cash cow before the streams can carry the firm is reckless.
                        scoreDelta -= 6; depDelta -= 6; newRevDelta -= 5; coachKey = `coach_r4_dump`; break;
                }

                switch (d.pitch) {
                    case `resilience`:
                        scoreDelta += 7; if (d.hedge === `multi`) coachKey = `coach_r4_resilience`; break;
                    case `decorate`:
                        // Decorating the cash cow — the board sees through it.
                        scoreDelta -= 5; coachKey = `coach_r4_decorate`; break;
                    case `single`:
                        scoreDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r4_singlepitch`; break;
                }

                if (d.conviction >= 60) { scoreDelta += 3; }
                else if (d.conviction <= 25) { scoreDelta -= 3; }

                summaryKey = (d.hedge === `multi` && d.lockin === `lockin` && d.pitch === `resilience`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Commit spend against the fixed A$12M budget. ----
            if (spend > 0) {
                const actual = Math.min(spend, ds.budgetLeft);
                ds.committed = Math.round((ds.committed + actual) * 100) / 100;
                ds.budgetLeft = Math.round((ds.budgetLeft - actual) * 100) / 100;
            }

            // ---- Apply deltas (clamped). ----
            ds.score = Math.max(0, Math.min(100, Math.round((ds.score + scoreDelta) * 10) / 10));
            ds.dependence = Math.max(0, Math.min(100, Math.round((ds.dependence + depDelta) * 10) / 10));
            ds.newRev = Math.max(0, Math.round((ds.newRev + newRevDelta) * 10) / 10);
            ds.exposure = Math.max(0, Math.min(100, Math.round((ds.exposure + exposureDelta) * 10) / 10));

            // ---- STICKY CAPS: the run-defining errors gate KPIs so a later good round cannot wash them out. ----
            // Headline anti-pattern: polishing the cash cow. Resilience cannot meaningfully recover and
            // dependence stays in the danger zone — you made the brittle thing shinier.
            if (ds.polishedCashCow) {
                ds.score = Math.min(ds.score, 52);
                ds.dependence = Math.max(ds.dependence, 70);
                ds.exposure = Math.max(ds.exposure, 60);
            }
            // Single-bet diversification: one new product is still concentration.
            if (ds.singleBet) {
                ds.score = Math.min(ds.score, 64);
                ds.dependence = Math.max(ds.dependence, 62);
            }
            // Cannibalisation paralysis: the AI revenue is ceded to rivals.
            if (ds.cannibalParalysis) {
                ds.score = Math.min(ds.score, 66);
                ds.exposure = Math.max(ds.exposure, 50);
            }
            // Products without a process: no engine for the next disruption.
            if (ds.noProcess) {
                ds.score = Math.min(ds.score, 60);
            }
            // One-size governance: the core's logic will kill the ventures.
            if (ds.oneSizeGov) {
                ds.score = Math.min(ds.score, 67);
                ds.newRev = Math.min(ds.newRev, 14);
            }
            // No hedge: a single wrong bet unravels the plan.
            if (ds.noHedge) {
                ds.score = Math.min(ds.score, 68);
                ds.exposure = Math.max(ds.exposure, 45);
            }

            // ---- Innovation ROI: projected new-stream revenue vs A$ committed. ----
            ds.roi = ds.committed > 0 ? Math.round((ds.newRev / ds.committed) * 10) / 10 : 0;

            ds.scoreHistory.push(ds.score);
            ds.depHistory.push(ds.dependence);
            ds.exposureHistory.push(ds.exposure);

            // ---- Persist the resilience score on the canonical performance path ----
            // This sim already exposes a resolvable score via the top-level ds.score and
            // results.score (express_resolveDomainScore / express_extractHistory Ruta 5 read them),
            // so the gradebook number was NOT broken. What was missing: the canonical
            // domainState.performance.overallScore (Ruta 1) and, crucially, performance.grade —
            // which express_extractMetrics surfaces to the gradebook/AGS and which was left null.
            // ds.score is unchanged; this only mirrors it onto performance + adds the grade letter.
            const scoreVal = Math.round(ds.score);
            ds.performance = { overallScore: scoreVal, grade: this._gradeLetter(scoreVal) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            return {
                period: state.currentPeriod,
                score: ds.score,
                overallScore: Math.round(ds.score),
                scoreDelta: Math.round(scoreDelta * 10) / 10,
                dependence: ds.dependence,
                newRev: ds.newRev,
                exposure: ds.exposure,
                budgetLeft: ds.budgetLeft,
                committed: ds.committed,
                roi: ds.roi,
                polishedCashCow: ds.polishedCashCow,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`scoreDisplay`, `domainState.score`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.resilience-card-score`);
                if (card) {
                    card.classList.toggle(`resilience-score-good`, n >= self.SCORE_TARGET);
                    card.classList.toggle(`resilience-score-bad`, n < 45);
                }
                return `${n}`;
            });

            uiManager.bind(`dependenceDisplay`, `domainState.dependence`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.resilience-card-dependence`);
                if (card) card.classList.toggle(`resilience-dep-good`, n < self.DEP_TARGET);
                return `${n}%`;
            });

            uiManager.bind(`newrevDisplay`, `domainState.newRev`, (v) => self._fmtMoney(Number(v)));
            uiManager.bind(`exposureDisplay`, `domainState.exposure`, (v) => `${Math.round(Number(v))}%`);
            uiManager.bind(`budgetDisplay`, `domainState.budgetLeft`, (v) => self._fmtMoney(Number(v)));

            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.resilience-roi-bar`);
                if (n <= 0) {
                    if (bar) { bar.classList.remove(`resilience-roi-good`, `resilience-roi-bad`); }
                    return window.mySimulation.t(`roi_pending`);
                }
                if (bar) {
                    bar.classList.toggle(`resilience-roi-good`, n >= 2);
                    bar.classList.toggle(`resilience-roi-bad`, n < 1);
                }
                return `${self._fmtNum(n)}×`;
            });

            // Urgency slider readout.
            const ur = document.getElementById(`urgencyInput`);
            const urReadout = document.getElementById(`urgencyReadout`);
            if (ur && urReadout) {
                urReadout.textContent = ur.value;
                ur.addEventListener(`input`, function() { urReadout.textContent = ur.value; });
            }
        }

        _fmtMoney(v) {
            // A$ with one decimal; es uses comma decimal.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            const shown = lang === `es` ? s.replace(`.`, `,`) : s;
            return `A$${shown}M`;
        }

        _fmtNum(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        // Letter grade surfaced to the gradebook / AGS via domainState.performance.grade.
        // (express_extractMetrics reads perf.grade; this sim previously left it null.) Derived
        // from the resilience score — the sim's own headline KPI; scoring is unchanged.
        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 70) return `B`;
            if (c >= 58) return `C`;
            if (c >= 45) return `D`;
            return `F`;
        }

        // Localize the internal (English) verdict tier id. The English id stays the stable key the
        // scoring logic keys on; the label is resolved for display only.
        _gradeLabel(id) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Resilience Built':          `verdict_built`,
                'Brittle Still':             `verdict_brittle`,
                'Polished the Cash Cow':     `verdict_polished`,
                'One Bet, New Concentration': `verdict_onebet`,
                'Products, No Engine':       `verdict_noengine`,
                'Ventures Strangled':        `verdict_strangled`,
                'Cannibalisation Paralysis': `verdict_paralysis`,
                'Unhedged':                  `verdict_unhedged`,
                'Partial Resilience':        `verdict_partial`
            };
            return map[id] ? t(map[id]) : id;
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, fallback) => (t ? t(k) : fallback);
            return {
                resilienceChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_score`, `Resilience score`),
                                data: [],
                                borderColor: `#56c4d3`,
                                backgroundColor: `rgba(86,196,211,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#56c4d3`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_dependence`, `Single-stream dependence (%)`),
                                data: [],
                                borderColor: `#e06c4f`,
                                backgroundColor: `rgba(224,108,79,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#e06c4f`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_exposure`, `Disruption exposure (%)`),
                                data: [],
                                borderColor: `#c9528f`,
                                backgroundColor: `rgba(201,82,143,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c9528f`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb4d2`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7e93b2` }, grid: { color: `rgba(120,150,190,0.12)` },
                                title: { display: true, text: L(`chart_axis_index`, `0–100`), color: `#7e93b2` }
                            },
                            x: {
                                ticks: { color: `#7e93b2` }, grid: { color: `rgba(120,150,190,0.08)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#7e93b2` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.scoreHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                resilienceChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.scoreHistory.map((v) => Math.round(v)) },
                        { data: ds.depHistory.map((v) => Math.round(v)) },
                        { data: ds.exposureHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const score = Math.round(ds.score);
            const dependence = Math.round(ds.dependence);
            const newRev = Math.round(ds.newRev * 10) / 10;
            const exposure = Math.round(ds.exposure);
            const roi = Math.round(ds.roi * 10) / 10;

            const depBelowTarget = dependence < this.DEP_TARGET;        // < 60% mandate met
            const scoreStrong = score >= this.SCORE_TARGET;             // >= 70
            const diversified = newRev >= 16;                           // a real portfolio of new revenue
            const hedged = !ds.noHedge && exposure <= 45;

            // Any sticky run-defining error blocks the top verdict.
            const anyStickyError = ds.polishedCashCow || ds.singleBet || ds.cannibalParalysis ||
                                   ds.noProcess || ds.oneSizeGov || ds.noHedge;

            let pattern = `mixed`;
            if (ds.polishedCashCow) pattern = `polish`;
            else if (ds.singleBet) pattern = `single`;
            else if (ds.cannibalParalysis) pattern = `paralysis`;
            else if (ds.noProcess) pattern = `noprocess`;
            else if (ds.oneSizeGov) pattern = `onesize`;
            else if (ds.noHedge) pattern = `nohedge`;
            else if (depBelowTarget && scoreStrong && diversified) pattern = `resilient`;

            let performance = `Brittle Still`;
            if (depBelowTarget && scoreStrong && diversified && hedged && !anyStickyError) {
                performance = `Resilience Built`;
            } else if (ds.polishedCashCow) {
                performance = `Polished the Cash Cow`;
            } else if (ds.singleBet) {
                performance = `One Bet, New Concentration`;
            } else if (ds.noProcess) {
                performance = `Products, No Engine`;
            } else if (ds.oneSizeGov) {
                performance = `Ventures Strangled`;
            } else if (ds.cannibalParalysis) {
                performance = `Cannibalisation Paralysis`;
            } else if (ds.noHedge) {
                performance = `Unhedged`;
            } else if (!anyStickyError && (depBelowTarget || (scoreStrong && diversified))) {
                // A clean run with no run-defining error that either met the mandate or
                // built strong, diversified resilience while narrowly missing it.
                performance = `Partial Resilience`;
            }

            const insights = [];
            if (performance === `Resilience Built`) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (pattern === `polish`) insights.push(window.mySimulation.t(`insight_polish`));
            else if (pattern === `single`) insights.push(window.mySimulation.t(`insight_single`));
            else if (pattern === `noprocess`) insights.push(window.mySimulation.t(`insight_noprocess`));
            else if (pattern === `onesize`) insights.push(window.mySimulation.t(`insight_onesize`));
            else if (pattern === `paralysis`) insights.push(window.mySimulation.t(`insight_paralysis`));
            else if (pattern === `nohedge`) insights.push(window.mySimulation.t(`insight_nohedge`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!depBelowTarget) insights.push(window.mySimulation.t(`insight_dep_high`));
            if (!ds.diagnosisRight) insights.push(window.mySimulation.t(`insight_misdiagnosed`));
            if (!diversified && !ds.polishedCashCow) insights.push(window.mySimulation.t(`insight_thin_newrev`));
            if (roi > 0 && roi < 1) insights.push(window.mySimulation.t(`insight_roi_low`));
            if (depBelowTarget && scoreStrong && exposure > 45) insights.push(window.mySimulation.t(`insight_exposure_left`));

            return {
                score: score,
                dependence: dependence,
                newRev: newRev,
                exposure: exposure,
                roi: roi,
                committed: Math.round(ds.committed * 10) / 10,
                depBelowTarget: depBelowTarget,
                scoreStrong: scoreStrong,
                diversified: diversified,
                hedged: hedged,
                anyStickyError: anyStickyError,
                pattern: pattern,
                grade: this._gradeLetter(score),
                performance: this._gradeLabel(performance),
                performanceId: performance,
                insights: insights
            };
        }

        // Rich, localized board debrief. Without this override the framework falls through to the
        // base "You completed N periods." stub and discards the score, verdict, KPIs and insights
        // this sim already computes. Self-contained, namespaced (.rr-cm-*) markup.
        formatCompletionMessage(summary) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const esc = (v) => String(v == null ? `` : v).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));

            const score = Math.round(Number(s.score) || 0);
            const grade = esc(s.grade || this._gradeLetter(score));
            const verdict = esc(s.performance || ``);
            const id = s.performanceId || ``;
            const tone = (id === `Resilience Built`) ? `good`
                : (id === `Partial Resilience`) ? `mid` : `bad`;

            const kpi = (label, value, ok) =>
                `<div class="rr-cm-kpi ${ok ? `rr-cm-ok` : `rr-cm-no`}"><div class="rr-cm-kpi-val">${value}</div><div class="rr-cm-kpi-lbl">${label}</div></div>`;
            const chip = (ok, label) =>
                `<span class="rr-cm-chip ${ok ? `rr-cm-chip-ok` : `rr-cm-chip-no`}">${ok ? `✓` : `✕`} ${label} · ${ok ? esc(t(`cm_met`)) : esc(t(`cm_missed`))}</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<ul class="rr-cm-insights">` + insights.map((x) => `<li>${esc(x)}</li>`).join(``) + `</ul>`
                : ``;

            return `
                <div class="rr-cm rr-cm-${tone}">
                    <div class="rr-cm-head">
                        <div class="rr-cm-verdict">${verdict}</div>
                        <div class="rr-cm-score"><span class="rr-cm-score-num">${score}</span><span class="rr-cm-score-max">/100</span><span class="rr-cm-grade">${esc(t(`cm_grade`))} ${grade}</span></div>
                    </div>
                    <div class="rr-cm-kpis">
                        ${kpi(esc(t(`cm_kpi_score`)), score, !!s.scoreStrong)}
                        ${kpi(esc(t(`cm_kpi_dependence`)), Math.round(Number(s.dependence) || 0) + `%`, !!s.depBelowTarget)}
                        ${kpi(esc(t(`cm_kpi_newrev`)), this._fmtMoney(Number(s.newRev) || 0), !!s.diversified)}
                        ${kpi(esc(t(`cm_kpi_exposure`)), Math.round(Number(s.exposure) || 0) + `%`, !!s.hedged)}
                    </div>
                    <div class="rr-cm-gates-h">${esc(t(`cm_gates_heading`))}</div>
                    <div class="rr-cm-gates">
                        ${chip(!!s.depBelowTarget, esc(t(`cm_gate_dependence`)))}
                        ${chip(!!s.scoreStrong, esc(t(`cm_gate_score`)))}
                        ${chip(!!s.diversified, esc(t(`cm_gate_diversified`)))}
                        ${chip(!!s.hedged, esc(t(`cm_gate_hedged`)))}
                    </div>
                    <div class="rr-cm-insights-h">${esc(t(`cm_insights_heading`))}</div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.polishedCashCow) return window.mySimulation.t(`hint_polish`);
            if (ds.singleBet && state.currentPeriod >= 2) return window.mySimulation.t(`hint_single`);
            if (ds.noProcess) return window.mySimulation.t(`hint_noprocess`);
            if (ds.oneSizeGov) return window.mySimulation.t(`hint_onesize`);
            if (ds.cannibalParalysis) return window.mySimulation.t(`hint_paralysis`);
            if (ds.dependence >= 70 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_dependence`);
            if (ds.exposure >= 55 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_exposure`);
            if (ds.score >= 70 && ds.dependence < 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.score`, label: `Score`, i18nKey: `col_score`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.dependence`, label: `Dependence`, i18nKey: `col_dependence`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.newRev`, label: `New rev`, i18nKey: `col_newrev`, formatter: (v) => self._fmtMoney(Number(v)) },
                { key: `results.exposure`, label: `Exposure`, i18nKey: `col_exposure`, formatter: (v) => `${Math.round(v)}%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

